package com.loopers.application.product
import org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.jdbc.Sql
@SpringBootTest @Sql("classpath:week4/product-query-seed.sql") class ProductCacheFailureTest @Autowired constructor(private val db:JdbcTemplate){@Test fun totalCacheFailureFallsBackToDb(){val down=object:ProductCache{override fun get(brandId:Long,limit:Int):List<ProductQueryService.Result>?=error("redis down");override fun put(brandId:Long,limit:Int,value:List<ProductQueryService.Result>)=error("redis down");override fun evict(brandId:Long)=error("redis down")};assertThat(ProductQueryService(db,down).find(7,20)).hasSize(20)}}
